func (t Answer) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Answer) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "choice":
		return t.AsChoiceAnswer()
	case "fill_blank":
		return t.AsFillBlankAnswer()
	case "text":
		return t.AsTextAnswer()
	case "true_false":
		return t.AsTrueFalseAnswer()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t Answer) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *Answer) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

